$string['formula_f12'] = 'score = clamp( round( 100 * (0.4*A + 0.35*B + 0.25*C) ), 0, 100 ); A = son tarih yoğunluğu; B = son teslim tarihi kümelemesi; C = kısa ihbar süreleri';
